/**
 * Helper to retrieve thumbnail URL for any game slug or id
 */
export function getGameThumbnail(slugOrId?: string, fallbackImage?: string): string {
  if (!slugOrId) return fallbackImage || "";
  const key = slugOrId.toLowerCase().trim().replace(/_/g, "-");
  return GAME_THUMBNAILS[key] || fallbackImage || "";
}
